/* ============================================================
   SCORING
   ============================================================ */
// 指定日を含む連続した生理期間の情報(開始日・何日目・前日も生理か)を返す
function periodInfo(days, ds) {
  const d = days[ds];
  if (!d || !d.period) return null;
  // 何日目か: 過去へ連続する生理日を数える
  let dayNum = 1;
  let cur = parseLocalDate(ds);
  while (true) {
    const prev = todayStr(addDays(cur, -1));
    if (days[prev] && days[prev].period) { dayNum++; cur = parseLocalDate(prev); }
    else break;
  }
  const startDs = todayStr(cur);
  // 翌日も生理か(終了日判定)
  const next = todayStr(addDays(parseLocalDate(ds), 1));
  const isLast = !(days[next] && days[next].period);
  const isFirst = dayNum === 1;
  return { dayNum, startDs, isFirst, isLast };
}

// 直近の生理開始日を求め、指定日がその周期の何日目かを返す
function cycleDayFor(days, ds) {
  const target = parseLocalDate(ds);
  let found = null;
  for (let i = 0; i <= 60; i++) {
    const cand = addDays(target, -i);
    const cds = todayStr(cand);
    const d = days[cds];
    if (d && d.period) {
      const prev = todayStr(addDays(cand, -1));
      const prevIsPeriod = days[prev] && days[prev].period;
      if (!prevIsPeriod) { found = cds; break; }
    }
  }
  if (!found) return null;
  const diff = Math.round((target - parseLocalDate(found)) / 86400000);
  return { cycleDay: diff + 1, startDs: found }; // 開始日を1日目
}

const emptyDay = () => ({
  meals: { breakfast: [], lunch: [], dinner: [], snack: [] },
  counters: { fruitG: 0, coffeeMl: 0, teaMl: 0, waterOnly: false },
  exercise: [],
  mood: "",
  violation: false,
  period: false,
  sleep: 0,
  moodQuality: 0,
  libido: 0,
});

function scoreDay(day, mode = "reboot") {
  if (!day) return { score: 0, rank: "-", parts: [] };
  const all = [...day.meals.breakfast, ...day.meals.lunch, ...day.meals.dinner, ...day.meals.snack];
  const flags = new Set();
  const vegNames = new Set();
  all.forEach((it) => {
    (it.f || []).forEach((f) => flags.add(f));
    if ((it.f || []).includes("veg")) vegNames.add(it.n);
  });
  const mealsLogged = ["breakfast","lunch","dinner"].filter(s => day.meals[s].length > 0).length;
  const parts = [];
  let score = 0;
  const add = (cond, pts, label) => { if (cond) score += pts; parts.push({ ok: cond, pts, label }); };
  add(mealsLogged === 3, 20, "3食すべて記録");
  add(vegNames.size >= 3, 15, "野菜3種以上");
  add(flags.has("fish"), 15, "魚を摂取");
  add(flags.has("fermented"), 10, "発酵食品を摂取");
  add(flags.has("organ"), 5, "内臓肉を摂取");
  const lim = MODE_LIMITS[mode] || MODE_LIMITS.reboot;
  add(day.counters.fruitG <= lim.fruit, 10, mode === "paleo" ? "フルーツ適量" : "フルーツ100g以内");
  const drinkOk = day.counters.waterOnly || (day.counters.coffeeMl <= lim.coffee && day.counters.teaMl <= lim.tea);
  add(drinkOk, 10, "コーヒー/茶が上限内");
  if (day.counters.waterOnly) { score += 5; parts.push({ ok: true, pts: 5, label: "水のみボーナス" }); }
  add(day.exercise.length > 0, 15, "運動を記録");
  let rank = "C";
  if (score >= 90) rank = "S"; else if (score >= 75) rank = "A"; else if (score >= 60) rank = "B";
  return { score, rank, parts, flags };
}

const RANK_COLOR = { S: C.greenDeep, A: C.green, B: C.carrot, C: C.inkFaint, "-": C.line };
const LEVEL_LABELS = ["未記録","とても悪い","悪い","普通","良い","とても良い"];

// レシピを食事記録に入れる際、採点用フラグ(veg/fish/fermented/organ/starch/fruit/nut)を推定
const TAG_TO_FLAG = { "魚": "fish", "発酵": "fermented", "ホルモン": "organ", "芋": "starch", "ナッツ": "nut", "フルーツ": "fruit" };
function recipeFlags(r) {
  const flags = new Set();
  (r.tags || []).forEach(t => { if (TAG_TO_FLAG[t]) flags.add(TAG_TO_FLAG[t]); });
  // 材料名から食材フラグ(特に野菜)を拾う
  const hay = (r.ing || []).join("") + (r.n || "");
  FOODS.forEach(f => {
    if ((f.f || []).length && hay.includes(f.n)) (f.f || []).forEach(fl => flags.add(fl));
  });
  return [...flags];
}

