const SPLASH_BG = "data:image/jpeg;base64,";
const SPLASH_FIG1 = "data:image/png;base64,";
const SPLASH_FIG2 = "data:image/png;base64,";
const SPLASH_FIG3 = "data:image/png;base64,";
const SPLASH_FIG4 = "data:image/png;base64,";
const SPLASH_FIG5 = "data:image/png;base64,";
const SPLASH_FIG6 = "data:image/png;base64,";
// 6人物のスケール・立ち位置(元画像の足元座標から算出した「傾斜を上る」オフセット)
// 6人物: 背景画像上の位置(x%, 足元y%)と高さ(%, 背景全体高さに対する比率)。
// 背景の斜めの下線に沿うよう実測値から算出。
// 6人物: 背景画像上の位置(x%, 足元y%)と高さ(%, 背景全体高さに対する比率)。
// 「ORIGINAL」の文字ブロック(実測 y=51.7%〜70.5%)と重ならないよう、十分な余白を取って上に配置。
// 6人物: 完成見本(963E0CED...png)から実測した位置(x中心%, 足元y%, 高さ%)。
// 文字「ORIGINAL」のすぐ上に密着し、左下→右上へ斜めに並ぶ配置。
const SPLASH_FIGURES = [
  { src: SPLASH_FIG1, x: 15.2, y: 56.8, h: 17.8 },
  { src: SPLASH_FIG2, x: 29.1, y: 55.3, h: 18.3 },
  { src: SPLASH_FIG3, x: 42.1, y: 53.9, h: 18.4 },
  { src: SPLASH_FIG4, x: 55.6, y: 52.0, h: 17.8 },
  { src: SPLASH_FIG5, x: 67.5, y: 51.3, h: 18.3 },
  { src: SPLASH_FIG6, x: 82.0, y: 50.0, h: 18.6 },
];
function Splash({ leaving }) {
  return (
    <div style={{ position: "fixed", inset: 0, background: "#EBF0DF", zIndex: 999,
      opacity: leaving ? 0 : 1, transition: "opacity 1.6s ease-in-out", overflow: "hidden" }}>
      {/* 背景と人物を同じ座標系(941:1672比率)で重ねるための枠 */}
      <div style={{ position: "absolute", inset: 0, maxWidth: 480, margin: "0 auto", overflow: "hidden" }}>
        {/* 背景(葉っぱ・アーチ・ORIGINALロゴ・キャッチコピー・斜めの下線) */}
        <img src={SPLASH_BG} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%",
          objectFit: "cover", animation: "splashBgIn 0.9s ease-out forwards", opacity: 0 }} />
        {/* 6人物: 太った人→旧石器時代の人へ左下から右上に、拡大や弾みを使わずゆっくり溶けるように出現 */}
        {SPLASH_FIGURES.map((f, i) => (
          <img key={i} src={f.src} alt="" style={{
            position: "absolute", left: `${f.x}%`, top: `${f.y}%`, height: `${f.h}%`,
            "--tx": "-50%", "--ty": "-100%",
            opacity: 0,
            animation: "splashFigIn 1.2s ease-out forwards",
            animationDelay: `${0.15 + i * 0.32}s`,
          }} />
        ))}
      </div>
      <style>{`
        @keyframes splashBgIn { 0% { opacity: 0; } 100% { opacity: 1; } }
        @keyframes splashFigIn {
          0%   { opacity: 0; transform: translate(var(--tx), var(--ty)) translateY(8px); filter: blur(7px); }
          100% { opacity: 1; transform: translate(var(--tx), var(--ty)) translateY(0);    filter: blur(0px); }
        }
      `}</style>
    </div>
  );
}

